def comps_conn(g, diag=True):
 h=len(g);w=len(g[0]);seen=set(); cs=[]
 ds=[(dr,dc) for dr in [-1,0,1] for dc in [-1,0,1] if (dr,dc)!=(0,0) and (diag or abs(dr)+abs(dc)==1)]
 for r in range(h):
  for c in range(w):
   if g[r][c]==0 and (r,c) not in seen:
    st=[(r,c)];seen.add((r,c));co=[]
    while st:
     x,y=st.pop();co.append((x,y))
     for dr,dc in ds:
      a,b=x+dr,y+dc
      if 0<=a<h and 0<=b<w and g[a][b]==0 and (a,b) not in seen: seen.add((a,b));st.append((a,b))
    cs.append(co)
 return sorted(cs,key=len,reverse=True)
